(function() {
  $(".newsletter .submit").click(function() {
    var data, email;
    email = $(".newsletter .email").val();
    if (email === "") {
      alert(Lang.pleaseFillTheForm);
      return;
    }
    $(".newsletter .submit").hide();
    $(".newsletter .loading").show();
    data = {
      email: email,
      lang: Lang.lang
    };
    return $.post("http://" + location.hostname + ":10000/v1/shop/newsletter", data, (function(response, textStatus) {
      console.log(response);
      if (response.error) {
        alert(Lang.errorRetry);
      } else {
        alert(Lang.successNewsletter + email);
        $(".newsletter .email").val("");
      }
      $(".submit").show();
      return $(".loading").hide();
    }), "json").error(function() {
      alert(Lang.errorRetry);
      $(".submit").show();
      return $(".loading").hide();
    });
  });

}).call(this);

